        else if (Messages.Count != _previousMessageCount && Messages.Count > 0 && _previousMessageCount == 0)
        {
            // Channel just loaded — scroll to bottom
            if (_module is not null)
                await _module.InvokeVoidAsync("scrollToBottom", _scrollContainer);
        }

        _previousMessageCount = Messages.Count;
    }

