            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

arguments.file_text:
namespace sv_04312e09b10146f0a5fd834ffb7a447e.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

export function initScrollObserver(container, dotnetRef) {
    if (!container) return;
    container._chatScrollHandler = () => {
        if (container.scrollTop === 0) {
            dotnetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };
    container.addEventListener('scroll', container._chatScrollHandler);
}

export function scrollToBottom(container) {
    if (!container) return;
    container.scrollTop = container.scrollHeight;
}

export function dispose(container) {
    if (!container || !container._chatScrollHandler) return;
    container.removeEventListener('scroll', container._chatScrollHandler);
    delete container._chatScrollHandler;
}

.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_04312e09b10146f0a5fd834ffb7a447e.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="main-and-thread">
        <MessageArea @ref="_messageArea"
                     Channel="_activeChannel"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     HasMoreMessages="_hasMoreMessages"
                     OnLoadMore="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />

        @if (_threadOpen && _threadRootMessage is not null)
        {
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    </div>
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _hasMoreMessages;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private MessageArea? _messageArea;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
            await SelectChannel(_channels[0]);
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        CloseThread();

        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _hasMoreMessages = _messages.Count >= PageSize;
        await BuildThreadReplyCounts();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread count
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (_activeChannel is null) return;
        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            await BuildThreadReplyCounts();
        }
        _hasMoreMessages = older.Count >= PageSize;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);

        if (_messageArea is not null)
        {
            StateHasChanged();
            await Task.Yield();
            await _messageArea.ScrollToBottomAsync();
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, Math.Max(_messages.Count, PageSize));
        }
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task BuildThreadReplyCounts()
    {
        _threadReplyCounts = [];
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var msg in _messages)
        {
            if (msg.ReplyToId is not null && rootIds.Contains(msg.ReplyToId.Value))
            {
                _threadReplyCounts.TryGetValue(msg.ReplyToId.Value, out var count);
                _threadReplyCounts[msg.ReplyToId.Value] = count + 1;
            }
        }

        // Also check via the service for threads not fully loaded in current page
        foreach (var rootId in rootIds)
        {
            if (!_threadReplyCounts.ContainsKey(rootId))
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                    _threadReplyCounts[rootId] = thread.Count;
            }
        }
    }
}

