export function initScrollObserver(container, dotnetRef) {
    if (!container) return;
    container._chatScrollHandler = () => {
        if (container.scrollTop === 0) {
            dotnetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };
    container.addEventListener('scroll', container._chatScrollHandler);
}

export function scrollToBottom(container) {
    if (!container) return;
    container.scrollTop = container.scrollHeight;
}

export function dispose(container) {
    if (!container || !container._chatScrollHandler) return;
    container.removeEventListener('scroll', container._chatScrollHandler);
    delete container._chatScrollHandler;
}

